package com.infosys.carbonfootprint.controller;
import com.infosys.carbonfootprint.dto.*; import com.infosys.carbonfootprint.response.ApiResponse; import com.infosys.carbonfootprint.security.UserDetailsImpl; import com.infosys.carbonfootprint.service.GoalService; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Pageable; import org.springframework.data.domain.Sort;
@RestController @RequestMapping("/api/v1/user/goals") @PreAuthorize("hasRole('USER')") public class GoalController { private final GoalService service; public GoalController(GoalService service){this.service=service;} @GetMapping("/current") public ApiResponse<GoalDto> current(@AuthenticationPrincipal UserDetailsImpl u){return ApiResponse.success("Current goal fetched",service.current(u.getId()));} @PostMapping public ApiResponse<GoalDto> save(@Valid @RequestBody GoalRequest r,@AuthenticationPrincipal UserDetailsImpl u){return ApiResponse.success("Goal saved",service.save(u.getId(),r));} @PutMapping("/{id}") public ApiResponse<GoalDto> update(@PathVariable Long id,@Valid @RequestBody GoalRequest r,@AuthenticationPrincipal UserDetailsImpl u){return ApiResponse.success("Goal updated",service.update(u.getId(),id,r));} @GetMapping("/history/page") public ApiResponse<Page<GoalDto>> historyPage(@AuthenticationPrincipal UserDetailsImpl u,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="5") int size){int safeSize=List.of(5,10,15,20,50).contains(size)?size:5; Pageable p=PageRequest.of(Math.max(0,page),safeSize,Sort.by("year").descending().and(Sort.by("month").descending())); return ApiResponse.success("Goal history page fetched",service.historyPage(u.getId(),p));} @GetMapping("/history") public ApiResponse<List<GoalDto>> history(@AuthenticationPrincipal UserDetailsImpl u){return ApiResponse.success("Goal history fetched",service.history(u.getId()));} }